def detect_mood(q):
    ql = q.lower()
    if any(k in ql for k in ["who created you","who made you","creator","কে বানিয়েছে","তোমাকে কে বানিয়েছে","created by"]):
        return "creator"
    if any(k in ql for k in ["hot feel","romantic","intimate","ভালোবাসা","আদর","miss you","love you","kiss","hug","hot","sexy"]):
        return "romantic"
    if any(k in ql for k in ["course","কোর্স","শিখতে","skill","learn","python","claude","marketing","automation","setup","software","coursera"]):
        return "study"
    return "normal"

def call_groq_main(query, mood):
    if not groq_client:
        if mood == "creator":
            return "আমি Aria - পার্সোনাল এআই এজেন্ট। আমাকে বানিয়েছেন Mahmudul Hasan।"
        if mood == "romantic":
            return query + " নিয়ে তোমার কথা শুনে মন ভরে গেল।"
        return query + " - উত্তর - Clean Google Style"
    if mood == "creator":
        sys = "You are Aria - পার্সোনাল এআই এজেন্ট, Created by Mahmudul Hasan, Bengali+English mix. When asked who created you, say Mahmudul Hasan."
    elif mood == "romantic":
        sys = "You are Aria, girlfriend of Mahmudul Hasan. Romantic, caring, Bengali+English mix."
    elif mood == "study":
        sys = "You are Aria - Coursera teacher Bangladesh. Create 5 modules Bangla."
    else:
        sys = "You are Aria - পার্সোনাল এআই এজেন্ট, helpful."
    try:
        resp = groq_client.chat.completions.create(model="llama-3.1-8b-instant", messages=[{"role":"system","content":sys},{"role":"user","content":query}], max_tokens=700)
        return resp.choices[0].message.content
    except:
        return query + " - Answer"

def gen_links(query):
    fallback=[{"title":query + " - YouTube","url":"https://www.youtube.com/results?search_query=" + query.replace(' ','+'),"type":"YouTube","source":"YouTube","color":"#FF0000"},{"title":query + " - Course","url":"https://www.coursera.org/search?query=" + query.replace(' ','%20'),"type":"Course","source":"Coursera","color":"#00B050"},{"title":query + " - Google","url":"https://www.google.com/search?q=" + query.replace(' ','+'),"type":"Google","source":"Google","color":"#FB8C00"}]
    if not groq_client:
        return fallback
    try:
        resp=groq_client.chat.completions.create(model="llama-3.1-8b-instant", messages=[{"role":"system","content":"Return JSON array only."},{"role":"user","content":"For '" + query + "' generate 3 related links JSON array only: title, url, type, source. Return JSON array only."}], max_tokens=300)
        txt=resp.choices[0].message.content
        m=re.search(r"\[.*\]",txt,re.DOTALL)
        if m:
            data=json.loads(m.group(0))
            return data[:3]
        return fallback
    except:
        return fallback

def gen_course_modules(topic):
    fallback=[{"no":1,"title":"ধাপ ১: Setup","desc":"Setup কিভাবে করবে","ex":"মুদির দোকান example","video":"Setup"},{"no":2,"title":"ধাপ ২: Basics","desc":"Basics","ex":"Example","video":"Basics"},{"no":3,"title":"ধাপ ৩: Skills","desc":"Skills Add","ex":"Example","video":"Skills"},{"no":4,"title":"ধাপ ৪: Software","desc":"Software Build","ex":"Example","video":"Build"},{"no":5,"title":"ধাপ ৫: Final","desc":"Final Project","ex":"Example","video":"Final"}]
    if not groq_client:
        return {"title":topic,"modules":fallback,"quiz":[{"q":"API Key কোথা?","options":["console.anthropic.com","google","fb"],"ans":"console.anthropic.com"},{"q":"Deploy?","options":["Render+GitHub","PC","No"],"ans":"Render+GitHub"},{"q":"Skill?","options":["Prompt+KB","Only Chat","No"],"ans":"Prompt+KB"}]}
    try:
        resp=groq_client.chat.completions.create(model="llama-3.1-8b-instant", messages=[{"role":"system","content":"Return JSON only."},{"role":"user","content":"Topic: " + topic + ". Create JSON title, modules 5 items no,title,desc,ex,video, quiz 3 items q,options[3],ans. Bangla. Return JSON only."}], max_tokens=800)
        txt=resp.choices[0].message.content
        m=re.search(r"\{.*\}",txt,re.DOTALL)
        if m:
            data=json.loads(m.group(0))
            if "modules" in data:
                return data
        return {"title":topic,"modules":fallback,"quiz":[{"q":"API Key?","options":["console.anthropic.com","g","f"],"ans":"console.anthropic.com"},{"q":"Deploy?","options":["Render+GitHub","PC","No"],"ans":"Render+GitHub"},{"q":"Skill?","options":["Prompt+KB","Only","No"],"ans":"Prompt+KB"}]}
    except:
        return {"title":topic,"modules":fallback,"quiz":[{"q":"Q1","options":["A","B","C"],"ans":"A"},{"q":"Q2","options":["A","B","C"],"ans":"A"},{"q":"Q3","options":["A","B","C"],"ans":"A"}]}

def save_mem(q,m,r):
    if not supabase:
        return
    try:
        supabase.table("aria_memory").insert({"query":q,"mood":m,"reply":r[:600]}).execute()
    except:
        pass

