g.addColorStop(0,"#fff"); g.addColorStop(1,"#e8f5e9");
ctx.fillStyle=g; ctx.fillRect(0,0,700,400);
ctx.strokeStyle="#0f9d58"; ctx.lineWidth=4; ctx.strokeRect(10,10,680,380);
ctx.fillStyle="#202124"; ctx.textAlign="center";
ctx.font="bold 26px Arial"; ctx.fillText("Certificate of Completion",350,70);
ctx.font="14px Arial"; ctx.fillStyle="#5f6368"; ctx.fillText("This certifies that",350,100);
ctx.font="bold 22px Arial"; ctx.fillStyle="#1a73e8"; ctx.fillText("Mahmudul Hasan",350,135);
ctx.font="14px Arial"; ctx.fillStyle="#202124"; ctx.fillText("has successfully completed",350,160);
