@app.get("/", response_class=HTMLResponse)
def home():
    return HTML_PAGE

@app.get("/chat")
def chat(q: str = Query(...)):
    mood=detect_mood(q)
    reply=call_groq_main(q,mood)
    save_mem(q,mood,reply)
    related=gen_links(q)
    return {"query":q,"mood":mood,"reply":reply,"related_links":related}

@app.get("/course_gen")
def course_gen(url: str = Query(...)):
    return gen_course_modules(url)

@app.get("/memory")
def memory():
    if not supabase:
        return {"supabase_connected":False}
    try:
        d=supabase.table("aria_memory").select("*").order("created_at", desc=True).limit(20).execute()
        return {"supabase_connected":True,"count":len(d.data),"data":d.data}
    except Exception as e:
        return {"supabase_connected":False,"error":str(e)}

@app.get("/health")
def health():
    return {"status":"ok","version":"8.0 Clean Working - No JS Crash - Course + Mic + Brain + Doodle Test + No Bottom Text","supabase":bool(supabase),"groq":bool(groq_client)}
